<script setup lang="ts">
import { onMounted, reactive, ref } from 'vue';import http from '@/api/http';import { useAuthStore } from '@/stores/auth';import { ElMessage } from 'element-plus';import type { Dict } from '@/types'
const auth=useAuthStore(),rows=ref<Dict[]>([]),detail=ref<Dict>(),warehouses=ref<Dict[]>([]),drawer=ref(false),receiveDialog=ref(false),receipt=reactive<Dict>({purchaseOrderId:'',warehouseId:'1',remark:'',items:[]})
async function load(){[rows.value,warehouses.value]=await Promise.all([http.get('/purchase-orders'),http.get('/warehouses')])}async function open(row:Dict){detail.value=await http.get(`/purchase-orders/${row.id}`);drawer.value=true}async function submit(row:Dict){await http.post(`/purchase-orders/${row.id}/submit`);ElMessage.success('订单已提交审批');load()}async function openReceive(row:Dict){detail.value=await http.get(`/purchase-orders/${row.id}`);receipt.purchaseOrderId=row.id;receipt.items=detail.value?.items.filter((x:Dict)=>Number(x.receivedQuantity)<Number(x.quantity)).map((x:Dict)=>({orderItemId:x.id,materialName:x.materialName,trackingMode:x.trackingMode,quantity:Number(x.quantity)-Number(x.receivedQuantity),batchNo:'',serialText:''}))||[];receiveDialog.value=true}async function receive(){const payload={...receipt,items:receipt.items.map((x:Dict)=>({...x,serialNumbers:x.serialText?x.serialText.split(/[,\n]/).map((v:string)=>v.trim()).filter(Boolean):[]}))};await http.post('/receipts',payload,{headers:{'Idempotency-Key':crypto.randomUUID()}});ElMessage.success('收货与库存入账成功');receiveDialog.value=false;load()}onMounted(load)
const status:Dict={DRAFT:'草稿',PENDING_APPROVAL:'审批中',APPROVED:'待收货',PARTIALLY_RECEIVED:'部分收货',RECEIVED:'已收货',CLOSED:'已关闭',REJECTED:'已驳回'}
</script>
<template><div class="page"><div class="page-head"><div><h1>采购订单</h1><p>商业条款审批、交付跟踪与分批收货</p></div><el-button @click="load">刷新</el-button></div><div class="panel panel-pad"><el-table :data="rows"><el-table-column prop="orderNo" label="订单号" width="170"/><el-table-column prop="supplier" label="供应商" min-width="200"/><el-table-column prop="purchaser" label="采购员"/><el-table-column prop="deliveryDate" label="交付日期"/><el-table-column prop="totalAmount" label="订单金额"><template #default="s">¥ {{Number(s.row.totalAmount).toLocaleString()}}</template></el-table-column><el-table-column label="状态"><template #default="s"><el-tag>{{status[s.row.status]}}</el-tag></template></el-table-column><el-table-column label="操作" width="210"><template #default="s"><el-button link @click="open(s.row)">详情</el-button><el-button v-if="['DRAFT','REJECTED'].includes(s.row.status)&&auth.can('purchaseorder:edit')" link type="primary" @click="submit(s.row)">提交审批</el-button><el-button v-if="['APPROVED','PARTIALLY_RECEIVED'].includes(s.row.status)&&auth.can('inventory:receive')" link type="success" @click="openReceive(s.row)">收货</el-button></template></el-table-column></el-table></div><el-drawer v-model="drawer" title="订单详情" size="680px"><el-descriptions :column="2" border><el-descriptions-item label="订单号">{{detail?.orderNo}}</el-descriptions-item><el-descriptions-item label="状态">{{status[detail?.status]}}</el-descriptions-item><el-descriptions-item label="金额">¥ {{detail?.totalAmount}}</el-descriptions-item><el-descriptions-item label="税率">{{Number(detail?.taxRate||0)*100}}%</el-descriptions-item><el-descriptions-item label="条款" :span="2">{{detail?.terms}}</el-descriptions-item></el-descriptions><el-table :data="detail?.items" style="margin-top:20px"><el-table-column prop="materialName" label="物资"/><el-table-column prop="quantity" label="订购"/><el-table-column prop="receivedQuantity" label="已收"/><el-table-column prop="unitPrice" label="单价"/></el-table></el-drawer><el-dialog v-model="receiveDialog" title="采购收货" width="850px"><el-form label-width="90px"><el-form-item label="入库仓库"><el-select v-model="receipt.warehouseId"><el-option v-for="w in warehouses" :key="w.id" :label="w.name" :value="w.id"/></el-select></el-form-item><el-form-item label="收货备注"><el-input v-model="receipt.remark"/></el-form-item></el-form><el-table :data="receipt.items"><el-table-column prop="materialName" label="物资"/><el-table-column label="本次数量" width="140"><template #default="s"><el-input-number v-model="s.row.quantity" :min="1"/></template></el-table-column><el-table-column label="批次号" width="160"><template #default="s"><el-input v-if="s.row.trackingMode==='BATCH'" v-model="s.row.batchNo"/></template></el-table-column><el-table-column label="序列号（逗号/换行分隔）" min-width="230"><template #default="s"><el-input v-if="s.row.trackingMode==='SERIAL'" v-model="s.row.serialText" type="textarea" :rows="2"/></template></el-table-column></el-table><template #footer><el-button @click="receiveDialog=false">取消</el-button><el-button type="primary" @click="receive">确认收货并入账</el-button></template></el-dialog></div></template>
